import { AESModeOfOperationECB } from './aes_ecb.mjs';

export function encryptUtf8Blocks(keyText, dataText) {
  const aes = new AESModeOfOperationECB(Buffer.from(keyText, 'utf8'));
  const data = Buffer.from(dataText, 'utf8');
  const ciphertexts = [];

  for (let offset = 0; offset < data.length; offset += 16) {
    const block = data.subarray(offset, offset + 16);
    ciphertexts.push(aes.encrypt(block));
  }

  return ciphertexts;
}

